105	/*
106	 * Prepare the kernel stack of a brand new process so that ret_from_exception
107	 * drops it into `entry_point` in user mode with argc/argv in a0/a1.
108	 */
109	static void init_pcb_stack(ptr_t kernel_stack, ptr_t user_stack, ptr_t entry_point,
110	                           pcb_t *new_pcb, int argc, uintptr_t argv)
111	{
112	    regs_context_t *pt_regs = (regs_context_t *)(kernel_stack - sizeof(regs_context_t));
113	    new_pcb->kernel_sp = kernel_stack - sizeof(regs_context_t);
114	
115	    /* the pcb slot may have been used before, do not inherit stale registers */
116	    memset(pt_regs, 0, sizeof(regs_context_t));
117	
118	    /* initialization registers: ra, sp, gp, a0, a1, sstatus, sepc, sscratch */
119	    pt_regs->regs[1] = (reg_t)entry_point;       //ra
120	    pt_regs->regs[2] = (reg_t)user_stack;        //sp
121	    pt_regs->regs[3] = (reg_t)__global_pointer$; //gp
122	    pt_regs->regs[10] = (reg_t)argc;             //a0, argc of main()
123	    pt_regs->regs[11] = (reg_t)argv;             //a1, argv of main()
124	    pt_regs->sepc = (reg_t)entry_point;          //sepc
125	    pt_regs->sstatus = (reg_t)SR_SPIE;           //SPP = 0, SPIE = 1
126	    pt_regs->sscratch = (reg_t)new_pcb;          //sscratch = tp
127	}
