129	/*
130	 * Copy the arguments of the caller onto the freshly created user stack of
131	 * `new_pcb` and return the user virtual address of the argv array.  The page
132	 * is filled in through the kernel's direct mapping, which is reachable no
133	 * matter which address space is currently installed.
134	 */
135	static uintptr_t init_user_stack(pcb_t *new_pcb, int argc, char *argv[])
136	{
137	    uintptr_t top_va = USER_STACK_ADDR;
138	    uintptr_t top_kva = alloc_page_helper(top_va - PAGE_SIZE,
139	                                          (uintptr_t)new_pcb->pgdir) + PAGE_SIZE;
140	    /* the last `top_va - va` bytes of the page hold the address `va` */
141	    #define STACK_KVA(va) (top_kva - (top_va - (uintptr_t)(va)))
142	
143	    uintptr_t string_va[MAX_EXEC_ARGC];
144	    uintptr_t sp = top_va;
145	    int i;
146	
147	    if (argc < 0 || argv == NULL) {
148	        argc = 0;
149	    }
150	    if (argc > MAX_EXEC_ARGC) {
151	        argc = MAX_EXEC_ARGC;
152	    }
153	
154	    /* the strings themselves, topmost first */
155	    for (i = argc - 1; i >= 0; i--) {
156	        int len = strlen(argv[i]) + 1;
157	        sp -= len;
158	        memcpy((uint8_t *)STACK_KVA(sp), (const uint8_t *)argv[i], (uint32_t)len);
159	        string_va[i] = sp;
160	    }
161	
162	    /* then the NULL terminated array pointing at them */
163	    sp = ROUNDDOWN(sp, sizeof(uintptr_t));
164	    sp -= (argc + 1) * sizeof(uintptr_t);
165	    uintptr_t *slot = (uintptr_t *)STACK_KVA(sp);
166	    for (i = 0; i < argc; i++) {
167	        slot[i] = string_va[i];
168	    }
169	    slot[argc] = 0;
170	
171	    uintptr_t argv_va = sp;
172	    /* the RISC-V ABI wants a 16 byte aligned stack pointer */
173	    new_pcb->user_sp = ROUNDDOWN(sp, 16);
174	
175	    #undef STACK_KVA
176	    return argv_va;
177	}
