20	    /* the strings themselves, topmost first */
21	    for (i = argc - 1; i >= 0; i--) {
22	        int len = strlen(argv[i]) + 1;
23	        sp -= len;
24	        memcpy((uint8_t *)STACK_KVA(sp), (const uint8_t *)argv[i], (uint32_t)len);
25	        string_va[i] = sp;
26	    }
27	
